WITH metrics AS (SELECT mktcode,tgtcode,MAX_BY(turnover,bizdate) AS turnover_value,MAX_BY(volume,bizdate) AS volume_value,AVG(volume) AS average_volume FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate IN (SELECT bizdate FROM `newzl`.`hsj_stock_hq_basic` GROUP BY bizdate ORDER BY bizdate DESC LIMIT 5) GROUP BY mktcode,tgtcode) SELECT a.mktcode,a.tgtcode,a.bizdate FROM (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14') a JOIN metrics m ON m.mktcode=a.mktcode AND m.tgtcode=a.tgtcode WHERE m.turnover_value>m.volume_value AND m.average_volume>0;
